from typing import List

class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        n = len(nums); i = 0
        while i < n:
            value = nums[i]
            if 1 <= value <= n and nums[value - 1] != value:
                nums[i], nums[value - 1] = nums[value - 1], nums[i]
            else:
                i += 1
        for i, value in enumerate(nums):
            if value != i + 1: return i + 1
        return n + 1

class Solution {
    public int firstMissingPositive(int[] nums) {
        int n = nums.length, i = 0;
        while (i < n) {
            int v = nums[i];
            if (v >= 1 && v <= n && nums[v - 1] != v) { int t = nums[i]; nums[i] = nums[v - 1]; nums[v - 1] = t; }
            else i++;
        }
        for (i = 0; i < n; i++) if (nums[i] != i + 1) return i + 1;
        return n + 1;
    }
}

