class Solution:
    def trap(self, height: List[int]) -> int:
        left, right = 0, len(height) - 1
        left_max = right_max = water = 0
        while left < right:
            if height[left] <= height[right]:
                left_max = max(left_max, height[left])
                water += left_max - height[left]
                left += 1
            else:
                right_max = max(right_max, height[right])
                water += right_max - height[right]
                right -= 1
        return water

class Solution {
    public int trap(int[] height) {
        int left = 0, right = height.length - 1, leftMax = 0, rightMax = 0, water = 0;
        while (left < right) {
            if (height[left] <= height[right]) { leftMax = Math.max(leftMax, height[left]); water += leftMax - height[left]; left++; }
            else { rightMax = Math.max(rightMax, height[right]); water += rightMax - height[right]; right--; }
        }
        return water;
    }
}

class Solution:
    def multiply(self, num1: str, num2: str) -> str:
        if num1 == '0' or num2 == '0': return '0'
        m, n = len(num1), len(num2); digits = [0] * (m + n)
        for i in range(m - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                total = (ord(num1[i]) - 48) * (ord(num2[j]) - 48) + digits[i + j + 1]
                digits[i + j + 1] = total % 10
                digits[i + j] += total // 10
        return ''.join(map(str, digits)).lstrip('0') or '0'

class Solution {
    public String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) return "0";
        int m = num1.length(), n = num2.length(); int[] d = new int[m + n];
        for (int i = m - 1; i >= 0; i--) for (int j = n - 1; j >= 0; j--) {
            int total = (num1.charAt(i) - '0') * (num2.charAt(j) - '0') + d[i + j + 1];
            d[i + j + 1] = total % 10; d[i + j] += total / 10;
        }
        StringBuilder out = new StringBuilder(); int i = 0; while (i < d.length && d[i] == 0) i++;
        for (; i < d.length; i++) out.append(d[i]);
        return out.length() == 0 ? "0" : out.toString();
    }
}

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m, n = len(s), len(p); dp = [[False] * (n + 1) for _ in range(m + 1)]; dp[0][0] = True
        for j in range(1, n + 1):
            if p[j - 1] == '*': dp[0][j] = dp[0][j - 1]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if p[j - 1] == '*': dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
                elif p[j - 1] == '?' or p[j - 1] == s[i - 1]: dp[i][j] = dp[i - 1][j - 1]
        return dp[m][n]

class Solution {
    public boolean isMatch(String s, String p) {
        int m=s.length(), n=p.length(); boolean[][] dp=new boolean[m+1][n+1]; dp[0][0]=true;
        for(int j=1;j<=n;j++) if(p.charAt(j-1)=='*') dp[0][j]=dp[0][j-1];
        for(int i=1;i<=m;i++) for(int j=1;j<=n;j++) {
            char c=p.charAt(j-1);
            if(c=='*') dp[i][j]=dp[i][j-1]||dp[i-1][j];
            else if(c=='?'||c==s.charAt(i-1)) dp[i][j]=dp[i-1][j-1];
        }
        return dp[m][n];
    }
}

