class Solution:
    def permuteUnique(self, nums: List[int]) -> List[List[int]]:
        nums.sort(); out=[]; path=[]; used=[False]*len(nums)
        def dfs():
            if len(path)==len(nums):out.append(path.copy());return
            for i,v in enumerate(nums):
                if used[i] or (i>0 and nums[i]==nums[i-1] and not used[i-1]):continue
                used[i]=True;path.append(v);dfs();path.pop();used[i]=False
        dfs();return out

import java.util.*;

class Solution {
    public List<List<Integer>> permuteUnique(int[] nums) { Arrays.sort(nums); List<List<Integer>> out=new ArrayList<>(); dfs(nums,new boolean[nums.length],new ArrayList<>(),out); return out; }
    private void dfs(int[] a,boolean[] used,List<Integer> path,List<List<Integer>> out){
        if(path.size()==a.length){out.add(new ArrayList<>(path));return;}
        for(int i=0;i<a.length;i++){if(used[i]||(i>0&&a[i]==a[i-1]&&!used[i-1]))continue;used[i]=true;path.add(a[i]);dfs(a,used,path,out);path.remove(path.size()-1);used[i]=false;}
